import{_ as t,o as s,c as n,a0 as e}from"./chunks/framework.DqMqoJl9.js";const h=JSON.parse('{"title":"五层拆解 + 两层成稿：把爆款视频变成可复用的创作资产","description":"","frontmatter":{"title":"五层拆解 + 两层成稿：把爆款视频变成可复用的创作资产","date":"2026-10-03T00:00:00.000Z","tags":["LLM","架构设计","Prompt 工程","多模态"]},"headers":[],"relativePath":"posts/breakdown-pipeline.md","filePath":"posts/breakdown-pipeline.md","lastUpdated":null}'),o={name:"posts/breakdown-pipeline.md"};function r(p,a,l,i,d,c){return s(),n("div",null,[...a[0]||(a[0]=[e(`<h1 id="五层拆解-两层成稿-把爆款视频变成可复用的创作资产" tabindex="-1">五层拆解 + 两层成稿：把爆款视频变成可复用的创作资产 <a class="header-anchor" href="#五层拆解-两层成稿-把爆款视频变成可复用的创作资产" aria-label="Permalink to &quot;五层拆解 + 两层成稿：把爆款视频变成可复用的创作资产&quot;">​</a></h1><p>帧间的核心不是&quot;生成一个视频&quot;，而是<strong>把爆款视频拆成可复用的元素，再带进新创作</strong>。拆解和成稿是两条独立管线，各有分工。</p><h2 id="拆解-五层递进" tabindex="-1">拆解：五层递进 <a class="header-anchor" href="#拆解-五层递进" aria-label="Permalink to &quot;拆解：五层递进&quot;">​</a></h2><p>拆解管线按信息粒度分层推进，每一层只负责一件事：</p><ol><li><strong>L1 外围建档</strong>：视频标题、标签、时长、封面、互动数据——先把&quot;外壳&quot;建起来</li><li><strong>L2 宏观扫描</strong>：整体结构、节奏、情绪曲线——看骨架</li><li><strong>L3 结构拆解</strong>：逐段拆开，转场、钩子、口播结构——看段落</li><li><strong>L4.5 内容精拆</strong>：台词逐句、镜头逐帧、BGM 卡点——看细节</li><li><strong>L5 元素提炼</strong>：沉淀成可复用的爆款元素（钩子句式、结构模板、情绪节奏）</li></ol><p>拆解用的多模态信息源：Whisper 转写台词、按 0.5~1 秒间隔抽帧做视觉理解、完播率等互动数据做筛选门槛。关键帧抽得够密，才撑得起&quot;逐镜头拆解&quot;。</p><h2 id="成稿-两层-确定性后处理" tabindex="-1">成稿：两层 + 确定性后处理 <a class="header-anchor" href="#成稿-两层-确定性后处理" aria-label="Permalink to &quot;成稿：两层 + 确定性后处理&quot;">​</a></h2><p>成稿管线刻意<strong>只用两次 LLM 调用</strong>（省成本、控时延）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>L1 一次调用 → 整体框架（结构化 JSON）</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Harness 确定性后处理（时间对齐、格式校验）</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>L2 一次调用 → 完整成稿（Markdown 编导脚本）</span></span></code></pre></div><p>关键在中间的 <strong>Harness</strong>：LLM 输出时间锚点、格式这类东西会漂，用确定性代码对齐、校验，而不是再丢给 LLM 修——能写代码解决的，不用第二次调用。</p><h2 id="元素库-拆解和创作的连接器" tabindex="-1">元素库：拆解和创作的连接器 <a class="header-anchor" href="#元素库-拆解和创作的连接器" aria-label="Permalink to &quot;元素库：拆解和创作的连接器&quot;">​</a></h2><p>拆解产出进<strong>元素库</strong>（跨片检索、质控），创作台成稿时按需提取带入。这样每拆一个视频，资产池就厚一点；创作不是从零开始，而是&quot;站在爆款肩膀上&quot;。</p><h2 id="交付物为什么是-视频说明书" tabindex="-1">交付物为什么是&quot;视频说明书&quot; <a class="header-anchor" href="#交付物为什么是-视频说明书" aria-label="Permalink to &quot;交付物为什么是&quot;视频说明书&quot;&quot;">​</a></h2><p>对编导来说，最有价值的不只是成片，而是<strong>为什么这样做、每一步怎么拍怎么剪</strong>。所以帧间交付的是包含拍摄建议、剪辑建议、节奏设计的&quot;视频说明书&quot;——它让非专业用户也能执行，也让爆款方法论可复制。</p><blockquote><p>面试可展开：为什么拆解要分层而不是一次问完？——单次调用信息密度有限，分层让每层 prompt 职责单一、可单独调优、可缓存复用。</p></blockquote>`,15)])])}const g=t(o,[["render",r]]);export{h as __pageData,g as default};
